package com.cloudscheduler.server.service;
import com.cloudscheduler.core.model.*; import com.cloudscheduler.core.scheduler.SchedulingStrategy; import java.util.*; import java.util.concurrent.*; import java.util.Comparator; import org.springframework.stereotype.Service;
@Service public class SchedulerService { private final Map<String,Task> tasks=new ConcurrentHashMap<>(); private final Map<String,VirtualMachine> vms=new ConcurrentHashMap<>(); private final Map<String,Phone> phones=new ConcurrentHashMap<>(); public Collection<Task> tasks(){return tasks.values();} public Collection<VirtualMachine> vms(){return vms.values();} public Collection<Phone> phones(){return phones.values();} public Task add(Task t){tasks.put(t.getId(),t);return t;} public VirtualMachine add(VirtualMachine v){vms.put(v.getId(),v);return v;} public Phone add(Phone p){phones.put(p.getId(),p);return p;} public List<Task> schedule(SchedulingStrategy s){List<Task>d=new ArrayList<>();for(Task t:tasks.values())if(t.getStatus()==TaskStatus.PENDING){Comparator<VirtualMachine>o=switch(s){case COST->Comparator.comparingDouble(VirtualMachine::getCostPerHour);case PERFORMANCE->Comparator.comparingDouble(VirtualMachine::utilization);case BALANCED->Comparator.comparingDouble(v->v.getCostPerHour()*(1+v.utilization()));};vms.values().stream().filter(v->v.canRun(t)).min(o).ifPresent(v->{v.allocate(t);t.setVmId(v.getId());t.setStatus(TaskStatus.SCHEDULED);d.add(t);});}return d;} }
